  # Every operation of the server's REST API.
  #
  # Included into {Client}, so these are called on a client rather than used
  # directly. They are listed here so that the documentation of the plumbing
  # and the documentation of the API stay separate things.
  module Operations
    # Every operation id, in specification order. The server exposes
    # 56 of them.
    OPERATION_IDS = %w[
      get_server_info
      get_health
      get_utcp_manual
      setup_auth
      de_auth
      re_auth
      ask_question
      list_notebooks
      add_notebook
      list_notebooks_from_nblm
      import_scraped_notebooks
      auto_discover_notebook
      search_notebooks
      get_library_stats
      delete_notebooks_from_nblm
      get_notebook
      update_notebook
      remove_notebook
      select_notebook
      create_notebook
      list_sessions
      close_session
      reset_session
      add_source
      delete_source
      delete_source_by_id
      delete_content
      list_sources
      read_source
      rename_source
      get_source_guide
      search_passages
      get_notebook_summary
      check_source_freshness
      get_chat_history
      delete_chat_history
      get_share_status
      share_notebook
      retry_content
      export_artifact
      revise_slide
      list_labels
      manage_labels
      generate_study_aid
      generate_mind_map
      research_sources
      generate_content
      download_content
      list_content
      create_note
      save_chat_to_note
      convert_note_to_source
      batch_to_vault
      list_notes
