      cleanup_data
    ].freeze

    # Server identity, version, and a pointer to the docs
    #
    # `GET /`
    #
    # @return [ServerInfo]
    # @raise [NotebookLM::Refused] when the server declines the request
    def get_server_info
      payload = call('get_server_info', :get, '/', enveloped: false)
      ServerInfo.new(payload)
    end

    # Server health check
    #
    # `GET /health`
    #
    # @return [GetHealthData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def get_health
      payload = call('get_health', :get, '/health')
      GetHealthData.new(payload)
    end

    # UTCP tool manual for this server
    #
    # The manual a Universal Tool Calling Protocol client reads before
    # calling anything. UTCP has no protocol server: the client reads this
    # once and then calls the routes below natively, so the manual is a
    # description of this same API rather than a second way into it.
    #
    # Generated from this specification, with the call addresses rebased on
    # the address the request arrived at. The same document is published
    # statically at `/utcp.json` on the documentation site. Behind the token
    # guard like every route but `/health`.
    #
    # `GET /utcp`
    #
    # @return [UtcpManual]
    # @raise [NotebookLM::Refused] when the server declines the request
    def get_utcp_manual
      payload = call('get_utcp_manual', :get, '/utcp', enveloped: false)
      UtcpManual.new(payload)
    end

    # First-time Google authentication (opens visible browser)
    #
    # `POST /setup-auth`
    #
    # @param show_browser [Boolean, nil]
    # @param account [String, nil]
    # @return [SetupAuthData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def setup_auth(show_browser: nil, account: nil)
      body = {}
      body['show_browser'] = show_browser unless show_browser.nil?
      body['account'] = account unless account.nil?
      payload = call('setup_auth', :post, '/setup-auth', body: body)
      SetupAuthData.new(payload)
    end

    # Logout, clear all credentials
    #
    # `POST /de-auth`
    #
    # @return [DeAuthData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def de_auth
      payload = call('de_auth', :post, '/de-auth')
      DeAuthData.new(payload)
    end

    # Re-authenticate or switch account
    #
    # `POST /re-auth`
    #
    # @param account [String, nil]
    # @return [ReAuthData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def re_auth(account: nil)
      body = {}
      body['account'] = account unless account.nil?
      payload = call('re_auth', :post, '/re-auth', body: body)
      ReAuthData.new(payload)
    end

    # Ask a question with citation-backed response
    #
    # `POST /ask`
    #
    # @param question [String]
