    #
    # @param content_id [String]
    # @param notebook_url [String, nil]
    # @param notebook_id [String, nil]
    # @return [DeleteContentData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def delete_content(content_id:, notebook_url: nil, notebook_id: nil)
