    # List a notebook's sources with their ids and titles
    #
    # RPC-backed (no browser). Returns `{ notebookId, count, sources: [{ id, title }] }`.
    # This is where the source ids for `/notebooks/{id}/sources/{sourceId}` come from.
    #
    # `GET /notebooks/{id}/sources`
    #
    # @param id [String]
    # @return [ListSourcesData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def list_sources(id:)
      payload = call('list_sources', :get, "/notebooks/#{id}/sources")
      ListSourcesData.new(payload)
    end

    # Read a source's indexed text, one page at a time
    #
    # RPC-backed (no browser). Returns the exact content NotebookLM reasons
    # over. Sources are long — the first PDF measured ran to 157,716
    # characters — so the response is paginated by default and carries
    # `totalChars`, `pageChars`, `offset`, `hasMore`, `nextCursor` and a
    # plain-language `continue` instruction. Pages are cut at the nearest
    # line break (tag close, in HTML), and concatenating every page
    # reproduces the document exactly. Pass `paginate=false` for the whole
    # document in one response. The `html` rendition preserves structure but
    # inlines images as base64 and is bigger.
    #
    # `GET /notebooks/{id}/sources/{sourceId}`
    #
    # @param id [String]
    # @param source_id [String]
    # @param format [String, nil]
    # @param paginate [Boolean, nil] Set to `false` to return the whole document in one response.
    # @param max_chars [Integer, nil] Page size in characters. Ignored when `paginate=false`.
    # @param cursor [Integer, nil] Resume point — the `nextCursor` returned by the previous page.
    # @return [ReadSourceData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def read_source(id:, source_id:, format: nil, paginate: nil, max_chars: nil, cursor: nil)
      query = {}
      query['format'] = format unless format.nil?
      query['paginate'] = paginate unless paginate.nil?
      query['max_chars'] = max_chars unless max_chars.nil?
      query['cursor'] = cursor unless cursor.nil?
      payload = call('read_source', :get, "/notebooks/#{id}/sources/#{source_id}", query: query)
      ReadSourceData.new(payload)
    end

    # Rename one source in place
    #
    # RPC-backed (no browser). An empty `title` is a 400.
    #
    # `PATCH /notebooks/{id}/sources/{sourceId}`
    #
    # @param id [String]
    # @param source_id [String]
    # @param title [String]
    # @return [RenameSourceData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def rename_source(id:, source_id:, title:)
      body = {}
      body['title'] = title
      payload = call('rename_source', :patch, "/notebooks/#{id}/sources/#{source_id}", body: body)
      RenameSourceData.new(payload)
    end

    # NotebookLM's own summary and key topics for one source
    #
    # RPC-backed (no browser). A source NotebookLM has not summarised yet
    # returns an empty `summary` and no topics.
    #
    # `GET /notebooks/{id}/sources/{sourceId}/guide`
    #
    # @param id [String]
    # @param source_id [String]
    # @return [GetSourceGuideData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def get_source_guide(id:, source_id:)
      payload = call('get_source_guide', :get, "/notebooks/#{id}/sources/#{source_id}/guide")
      GetSourceGuideData.new(payload)
    end

    # Ranked passages from the notebook's index, without generating an answer
    #
    # RPC-backed (no browser). Retrieval rather than question answering:
    # nothing is generated and no generation quota is spent. Rank is global
    # across sources and lower is better. `start` / `end` are character
    # offsets into the source's full text, and are `null` when the server
    # did not give them.
    #
    # `POST /notebooks/{id}/search`
    #
    # @param id [String]
    # @param query [String]
    # @param source_ids [Array<String>, nil] Restrict to these source UUIDs. Omit to search them all.
    # @param source_names [Array<String>, nil] Restrict by source title; an ambiguous title is an error.
    # @param limit [Integer, nil] Keep at most this many passages, best rank first.
    # @return [SearchPassagesData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def search_passages(id:, query:, source_ids: nil, source_names: nil, limit: nil)
      body = {}
      body['query'] = query
      body['source_ids'] = source_ids unless source_ids.nil?
      body['source_names'] = source_names unless source_names.nil?
      body['limit'] = limit unless limit.nil?
      payload = call('search_passages', :post, "/notebooks/#{id}/search", body: body)
      SearchPassagesData.new(payload)
    end

    # A notebook's own summary of its sources, and the questions it suggests
    #
    # RPC-backed (no browser). Cheaper than asking a question to find out
    # what a notebook holds.
    #
    # `GET /notebooks/{id}/summary`
    #
    # @param id [String]
    # @return [GetNotebookSummaryData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def get_notebook_summary(id:)
      payload = call('get_notebook_summary', :get, "/notebooks/#{id}/summary")
      GetNotebookSummaryData.new(payload)
    end

    # Have the notebook's URL / Drive sources drifted?
    #
    # RPC-backed (no browser). Checks every source unless `source_id`
    # narrows it. `stale: null` means the server did not answer for that
    # source — not that it is current.
    #
    # `GET /notebooks/{id}/freshness`
    #
    # @param id [String]
    # @param source_id [String, nil]
    # @return [CheckSourceFreshnessData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def check_source_freshness(id:, source_id: nil)
      query = {}
      query['source_id'] = source_id unless source_id.nil?
      payload = call('check_source_freshness', :get, "/notebooks/#{id}/freshness", query: query)
      CheckSourceFreshnessData.new(payload)
    end

    # Read back the recorded questions and answers, newest first
    #
    # RPC-backed (no browser). NotebookLM exposes only the most recent
    # conversation per notebook; older ones cannot be listed.
    #
    # `GET /notebooks/{id}/chat`
    #
    # @param id [String]
    # @param conversation_id [String, nil]
    # @param limit [Integer, nil]
    # @return [GetChatHistoryData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def get_chat_history(id:, conversation_id: nil, limit: nil)
      query = {}
      query['conversation_id'] = conversation_id unless conversation_id.nil?
      query['limit'] = limit unless limit.nil?
      payload = call('get_chat_history', :get, "/notebooks/#{id}/chat", query: query)
      GetChatHistoryData.new(payload)
    end

    # Clear the chat history
    #
    # The web UI's "Delete history". NotebookLM has no per-turn delete, so
    # the whole conversation goes. Nothing to delete is reported as
    # `deleted: false`, not as a failure.
    #
    # `DELETE /notebooks/{id}/chat`
    #
    # @param id [String]
    # @param conversation_id [String, nil]
    # @return [DeleteChatHistoryData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def delete_chat_history(id:, conversation_id: nil)
      query = {}
      query['conversation_id'] = conversation_id unless conversation_id.nil?
      payload = call('delete_chat_history', :delete, "/notebooks/#{id}/chat", query: query)
      DeleteChatHistoryData.new(payload)
    end

    # Read a notebook's sharing status
    #
    # `GET /notebooks/{id}/share`
    #
    # @param id [String]
    # @return [GetShareStatusData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def get_share_status(id:)
      payload = call('get_share_status', :get, "/notebooks/#{id}/share")
      GetShareStatusData.new(payload)
    end

    # Toggle the public link
    #
    # `PUT /notebooks/{id}/share`
    #
    # @param id [String]
    # @param public [Boolean]
    # @return [ShareNotebookData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def share_notebook(id:, public:)
      body = {}
      body['public'] = public
      payload = call('share_notebook', :put, "/notebooks/#{id}/share", body: body)
      ShareNotebookData.new(payload)
    end

    # Retry a failed generation, keeping the same artifact id
    #
    # RPC-backed. The artifact is not deleted and not replaced: the same id
    # goes back to `generating`, so a reference the caller already holds
    # stays valid. Deleting and regenerating instead mints a new id.
    #
    # A refusal (rate limit, quota, or an artifact the backend will not
    # retry) comes back as an error. An accepted retry can still fail again
    # on Google's side — poll `GET /content` for the outcome.
    #
    # `POST /content/{artifactId}/retry`
    #
    # @param artifact_id [String]
    # @param notebook_id [String, nil]
    # @param notebook_url [String, nil]
    # @return [RetryContentData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def retry_content(artifact_id:, notebook_id: nil, notebook_url: nil)
      body = {}
      body['notebook_id'] = notebook_id unless notebook_id.nil?
      body['notebook_url'] = notebook_url unless notebook_url.nil?
      payload = call('retry_content', :post, "/content/#{artifact_id}/retry", body: body)
      RetryContentData.new(payload)
    end

    # Export a finished artifact to Google Docs or Sheets
    #
    # RPC-backed. `documentUrl` is `null` when the reply carried no Drive
    # link — the export may still have succeeded; check Drive.
    #
    # `POST /content/{artifactId}/export`
    #
    # @param artifact_id [String]
    # @param notebook_id [String, nil]
    # @param notebook_url [String, nil]
    # @param target [String, nil]
    # @param title [String, nil]
    # @return [ExportArtifactData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def export_artifact(artifact_id:, notebook_id: nil, notebook_url: nil, target: nil, title: nil)
      body = {}
      body['notebook_id'] = notebook_id unless notebook_id.nil?
      body['notebook_url'] = notebook_url unless notebook_url.nil?
      body['target'] = target unless target.nil?
      body['title'] = title unless title.nil?
      payload = call('export_artifact', :post, "/content/#{artifact_id}/export", body: body)
      ExportArtifactData.new(payload)
    end

    # Revise one slide of an existing deck from a prompt
    #
    # RPC-backed. `slide_index` is zero-based. Returns as soon as the
    # revision is accepted; poll `GET /content` for the finished deck.
    #
    # `POST /content/{artifactId}/revise-slide`
    #
    # @param artifact_id [String]
    # @param notebook_id [String, nil]
    # @param notebook_url [String, nil]
    # @param slide_index [Integer]
    # @param prompt [String]
    # @return [ReviseSlideData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def revise_slide(artifact_id:, slide_index:, prompt:, notebook_id: nil, notebook_url: nil)
      body = {}
      body['notebook_id'] = notebook_id unless notebook_id.nil?
      body['notebook_url'] = notebook_url unless notebook_url.nil?
      body['slide_index'] = slide_index
      body['prompt'] = prompt
      payload = call('revise_slide', :post, "/content/#{artifact_id}/revise-slide", body: body)
      ReviseSlideData.new(payload)
    end

    # List a notebook's source labels
    #
    # `GET /notebooks/{id}/labels`
    #
    # @param id [String]
    # @return [ListLabelsData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def list_labels(id:)
      payload = call('list_labels', :get, "/notebooks/#{id}/labels")
      ListLabelsData.new(payload)
    end

    # Create or delete source labels
    #
    # `POST /notebooks/{id}/labels`
    #
    # @param id [String]
    # @param action [String, nil]
    # @param name [String, nil]
    # @param emoji [String, nil]
    # @param label_ids [Array<String>, nil]
    # @return [ManageLabelsData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def manage_labels(id:, action: nil, name: nil, emoji: nil, label_ids: nil)
      body = {}
      body['action'] = action unless action.nil?
      body['name'] = name unless name.nil?
      body['emoji'] = emoji unless emoji.nil?
      body['label_ids'] = label_ids unless label_ids.nil?
      payload = call('manage_labels', :post, "/notebooks/#{id}/labels", body: body)
      ManageLabelsData.new(payload)
    end

    # Generate a study aid (flashcards or quiz)
    #
    # `POST /content/study-aid`
    #
    # @param notebook_id [String, nil]
    # @param notebook_url [String, nil]
    # @param kind [String]
    # @param focus [String, nil]
    # @return [GenerateStudyAidData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def generate_study_aid(kind:, notebook_id: nil, notebook_url: nil, focus: nil)
      body = {}
      body['notebook_id'] = notebook_id unless notebook_id.nil?
      body['notebook_url'] = notebook_url unless notebook_url.nil?
      body['kind'] = kind
      body['focus'] = focus unless focus.nil?
      payload = call('generate_study_aid', :post, '/content/study-aid', body: body)
      GenerateStudyAidData.new(payload)
    end

    # Generate and save a mind map
    #
    # `POST /content/mind-map`
    #
    # @param notebook_id [String, nil]
    # @param notebook_url [String, nil]
    # @param title [String, nil]
    # @return [GenerateMindMapData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def generate_mind_map(notebook_id: nil, notebook_url: nil, title: nil)
      body = {}
      body['notebook_id'] = notebook_id unless notebook_id.nil?
      body['notebook_url'] = notebook_url unless notebook_url.nil?
      body['title'] = title unless title.nil?
      payload = call('generate_mind_map', :post, '/content/mind-map', body: body)
      GenerateMindMapData.new(payload)
    end

    # Discover web sources for a notebook (Fast Research), optionally importing them
    #
    # `POST /content/research`
    #
    # @param notebook_id [String, nil]
    # @param notebook_url [String, nil]
    # @param query [String]
    # @param import [Boolean, nil]
    # @return [ResearchSourcesData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def research_sources(query:, notebook_id: nil, notebook_url: nil, import: nil)
      body = {}
      body['notebook_id'] = notebook_id unless notebook_id.nil?
      body['notebook_url'] = notebook_url unless notebook_url.nil?
      body['query'] = query
      body['import'] = import unless import.nil?
      payload = call('research_sources', :post, '/content/research', body: body)
      ResearchSourcesData.new(payload)
    end

    # Generate Studio content (audio, video, infographic, report, presentation, data table)
    #
    # `POST /content/generate`
    #
    # @param content_type [String]
    # @param language [String, nil]
    # @param custom_instructions [String, nil]
    # @param video_style [String, nil]
    # @param video_format [String, nil]
    # @param infographic_format [String, nil]
    # @param report_format [String, nil]
    # @param presentation_style [String, nil]
    # @param presentation_length [String, nil]
    # @return [GenerateContentData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def generate_content(content_type:, language: nil, custom_instructions: nil, video_style: nil, video_format: nil, infographic_format: nil, report_format: nil, presentation_style: nil, presentation_length: nil)
      body = {}
      body['content_type'] = content_type
      body['language'] = language unless language.nil?
      body['custom_instructions'] = custom_instructions unless custom_instructions.nil?
      body['video_style'] = video_style unless video_style.nil?
      body['video_format'] = video_format unless video_format.nil?
      body['infographic_format'] = infographic_format unless infographic_format.nil?
      body['report_format'] = report_format unless report_format.nil?
      body['presentation_style'] = presentation_style unless presentation_style.nil?
      body['presentation_length'] = presentation_length unless presentation_length.nil?
      payload = call('generate_content', :post, '/content/generate', body: body)
      GenerateContentData.new(payload)
    end

    # Download a generated artifact (WAV, MP4, PNG)
    #
    # `GET /content/download`
    #
    # @param content_id [String, nil]
    # @return [DownloadContentData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def download_content(content_id: nil)
      query = {}
      query['content_id'] = content_id unless content_id.nil?
      payload = call('download_content', :get, '/content/download', query: query)
      DownloadContentData.new(payload)
    end

    # List sources and generated content for the active notebook
    #
    # `GET /content`
    #
    # @return [ListContentData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def list_content
      payload = call('list_content', :get, '/content')
      ListContentData.new(payload)
    end

    # Create a note in the active notebook
    #
    # `POST /content/notes`
    #
    # @return [CreateNoteData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def create_note
      payload = call('create_note', :post, '/content/notes')
      CreateNoteData.new(payload)
    end

    # Save the current chat discussion as a note
    #
    # `POST /content/chat-to-note`
    #
    # @return [SaveChatToNoteData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def save_chat_to_note
      payload = call('save_chat_to_note', :post, '/content/chat-to-note')
      SaveChatToNoteData.new(payload)
    end

    # Convert a note into a NotebookLM source
    #
    # `POST /content/notes/{noteTitle}/to-source`
    #
    # @param note_title [String]
    # @return [ConvertNoteToSourceData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def convert_note_to_source(note_title:)
      payload = call('convert_note_to_source', :post, "/content/notes/#{note_title}/to-source")
      ConvertNoteToSourceData.new(payload)
    end

    # Run a batch of questions and write each answer to a vault directory
    #
    # Long-running: one NotebookLM answer per question, written as a markdown
    # file conforming to the `nblm-answer-v1` schema. Size the client timeout
    # accordingly (and the reverse-proxy read timeout, if any).
    #
    # `POST /batch-to-vault`
    #
    # @param questions [Array<String>]
    # @param notebook_id [String, nil]
    # @param notebook_url [String, nil]
    # @param vault_dir [String, nil]
    # @param slug_prefix [String, nil]
    # @param source_format [String, nil]
    # @param sleep_between_ms [Integer, nil]
    # @param session_id [String, nil]
    # @return [BatchToVaultData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def batch_to_vault(questions:, notebook_id: nil, notebook_url: nil, vault_dir: nil, slug_prefix: nil, source_format: nil, sleep_between_ms: nil, session_id: nil)
      body = {}
      body['questions'] = questions
      body['notebook_id'] = notebook_id unless notebook_id.nil?
      body['notebook_url'] = notebook_url unless notebook_url.nil?
      body['vault_dir'] = vault_dir unless vault_dir.nil?
      body['slug_prefix'] = slug_prefix unless slug_prefix.nil?
      body['source_format'] = source_format unless source_format.nil?
      body['sleep_between_ms'] = sleep_between_ms unless sleep_between_ms.nil?
      body['session_id'] = session_id unless session_id.nil?
      payload = call('batch_to_vault', :post, '/batch-to-vault', body: body)
      BatchToVaultData.new(payload)
    end

    # List the notebook's notes
    #
    # `POST /content/notes/list`
    #
    # @param notebook_url [String, nil]
    # @param session_id [String, nil]
    # @return [ListNotesData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def list_notes(notebook_url: nil, session_id: nil)
      body = {}
      body['notebook_url'] = notebook_url unless notebook_url.nil?
      body['session_id'] = session_id unless session_id.nil?
      payload = call('list_notes', :post, '/content/notes/list', body: body)
      ListNotesData.new(payload)
    end

    # Read one note's content, by title or id
    #
    # `POST /content/notes/get`
    #
    # @param note_title [String, nil]
    # @param note_id [String, nil]
    # @param notebook_url [String, nil]
    # @param session_id [String, nil]
    # @return [GetNoteData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def get_note(note_title: nil, note_id: nil, notebook_url: nil, session_id: nil)
      body = {}
      body['note_title'] = note_title unless note_title.nil?
      body['note_id'] = note_id unless note_id.nil?
      body['notebook_url'] = notebook_url unless notebook_url.nil?
      body['session_id'] = session_id unless session_id.nil?
      payload = call('get_note', :post, '/content/notes/get', body: body)
      GetNoteData.new(payload)
    end

    # Wipe all local data (requires confirmation)
    #
    # `POST /cleanup-data`
    #
    # @param confirm [Boolean, nil]
    # @return [CleanupDataData]
    # @raise [NotebookLM::Refused] when the server declines the request
    def cleanup_data(confirm: nil)
      body = {}
      body['confirm'] = confirm unless confirm.nil?
      payload = call('cleanup_data', :post, '/cleanup-data', body: body)
      CleanupDataData.new(payload)
    end
  end

  class Client
    include Operations
  end
end
